export const MAX_DRAFT_PICKS = 3;

export interface WeeklyPickCandidate {
  interestId: string;
  candidateRank: number;
  sourceId: string;
  sourceProviderId: string;
  sourceDisplayName: string;
  featuredMediaItemId: string;
  featuredMediaTitle: string;
  featuredMediaPublishedAt: string;
  lastPickedPeriodStart: string | null;
}

export interface WeeklyPickDraft {
  interestId: string;
  periodStart: string;
  periodEnd: string;
  publishPayload: readonly {
    sourceId: string;
    featuredMediaItemId: string;
    reason: null;
  }[];
  review: readonly {
    candidateRank: number;
    sourceDisplayName: string;
    sourceProviderId: string;
    featuredMediaTitle: string;
    featuredMediaPublishedAt: string;
    lastPickedPeriodStart: string | null;
  }[];
}

/** Parses only the fields needed by the editorial preparation step. */
export function parseWeeklyPickCandidates(value: unknown): WeeklyPickCandidate[] {
  if (!Array.isArray(value)) throw new Error("Candidate response must be a list.");
  return value.map((row, index) => {
    if (!isRecord(row)) throw new Error(`Candidate ${index + 1} is invalid.`);
    const candidateRank = integer(row.candidate_rank);
    const lastPicked = nullableIsoDate(row.last_picked_period_start);
    const candidate: WeeklyPickCandidate = {
      interestId: nonEmptyString(row.interest_id),
      candidateRank,
      sourceId: uuid(row.source_id),
      sourceProviderId: nonEmptyString(row.source_provider_id),
      sourceDisplayName: nonEmptyString(row.source_display_name),
      featuredMediaItemId: uuid(row.featured_media_item_id),
      featuredMediaTitle: nonEmptyString(row.featured_media_title),
      featuredMediaPublishedAt: isoDateTime(row.featured_media_published_at),
      lastPickedPeriodStart: lastPicked,
    };
    if (candidateRank < 1 || candidateRank > 12) throw new Error(`Candidate ${index + 1} has an invalid rank.`);
    return candidate;
  });
}

/**
 * Builds reviewable, non-published drafts. Selection is deterministic and
 * limited to the database-ranked verified cache; reasons remain unset until
 * an editor or a future bounded AI step reviews the draft.
 */
export function buildWeeklyPickDrafts(
  candidates: readonly WeeklyPickCandidate[],
  periodStart: string,
  maxPicks: number = MAX_DRAFT_PICKS,
): WeeklyPickDraft[] {
  const periodEnd = weeklyPeriodEnd(periodStart);
  if (!Number.isInteger(maxPicks) || maxPicks < 1 || maxPicks > MAX_DRAFT_PICKS) {
    throw new Error(`Draft pick limit must be between 1 and ${MAX_DRAFT_PICKS}.`);
  }

  const grouped = new Map<string, WeeklyPickCandidate[]>();
  for (const candidate of candidates) {
    const current = grouped.get(candidate.interestId) ?? [];
    current.push(candidate);
    grouped.set(candidate.interestId, current);
  }

  return [...grouped.entries()].map(([interestId, values]) => {
    const seenSources = new Set<string>();
    const selected = [...values]
      .sort((left, right) => left.candidateRank - right.candidateRank || left.sourceId.localeCompare(right.sourceId))
      .filter((candidate) => {
        if (seenSources.has(candidate.sourceId)) return false;
        seenSources.add(candidate.sourceId);
        return true;
      })
      .slice(0, maxPicks);

    return {
      interestId,
      periodStart,
      periodEnd,
      publishPayload: selected.map((candidate) => ({
        sourceId: candidate.sourceId,
        featuredMediaItemId: candidate.featuredMediaItemId,
        reason: null,
      })),
      review: selected.map((candidate) => ({
        candidateRank: candidate.candidateRank,
        sourceDisplayName: candidate.sourceDisplayName,
        sourceProviderId: candidate.sourceProviderId,
        featuredMediaTitle: candidate.featuredMediaTitle,
        featuredMediaPublishedAt: candidate.featuredMediaPublishedAt,
        lastPickedPeriodStart: candidate.lastPickedPeriodStart,
      })),
    };
  });
}

export function weeklyPeriodEnd(periodStart: string): string {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(periodStart)) throw new Error("Period start must use YYYY-MM-DD.");
  const start = new Date(`${periodStart}T00:00:00.000Z`);
  if (!Number.isFinite(start.getTime()) || start.toISOString().slice(0, 10) !== periodStart || start.getUTCDay() !== 1) {
    throw new Error("Period start must be a valid Monday.");
  }
  start.setUTCDate(start.getUTCDate() + 6);
  return start.toISOString().slice(0, 10);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function nonEmptyString(value: unknown): string {
  if (typeof value !== "string" || value.length === 0) throw new Error("Required candidate text is missing.");
  return value;
}

function integer(value: unknown): number {
  if (typeof value !== "number" || !Number.isInteger(value)) throw new Error("Candidate rank is invalid.");
  return value;
}

function uuid(value: unknown): string {
  const parsed = nonEmptyString(value);
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(parsed)) {
    throw new Error("Candidate identifier is invalid.");
  }
  return parsed;
}

function isoDateTime(value: unknown): string {
  const parsed = nonEmptyString(value);
  if (!Number.isFinite(Date.parse(parsed))) throw new Error("Candidate timestamp is invalid.");
  return parsed;
}

function nullableIsoDate(value: unknown): string | null {
  if (value === null) return null;
  const parsed = nonEmptyString(value);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(parsed) || !Number.isFinite(Date.parse(`${parsed}T00:00:00.000Z`))) {
    throw new Error("Previous publication date is invalid.");
  }
  return parsed;
}
